{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "title_h2",
        "chart_intro",
        "visitor_table",
        "divider_1",
        "busiest_day_card"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Website Visitor Trend Analysis",
        "variant": "h1"
      },
      "children": []
    },
    "title_h2": {
      "type": "Text",
      "props": {
        "text": "Daily Visitor Trends and Busiest Day",
        "variant": "h2"
      },
      "children": []
    },
    "chart_intro": {
      "type": "Text",
      "props": {
        "text": "Here is the provided website visitor data for the week, visualized to show trends and identify the busiest day:"
      },
      "children": []
    },
    "visitor_table": {
      "type": "Table",
      "props": {
        "title": "Weekly Website Visitor Trend",
        "columns": [
          {
            "key": "Day",
            "label": "Day"
          },
          {
            "key": "Visitors",
            "label": "Visitors"
          }
        ],
        "rows": [
          {
            "Day": "Mon",
            "Visitors": 500
          },
          {
            "Day": "Tue",
            "Visitors": 620
          },
          {
            "Day": "Wed",
            "Visitors": 580
          },
          {
            "Day": "Thu",
            "Visitors": 710
          },
          {
            "Day": "Fri",
            "Visitors": 650
          },
          {
            "Day": "Sat",
            "Visitors": 400
          },
          {
            "Day": "Sun",
            "Visitors": 350
          }
        ],
        "domain": "generic",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "divider_1": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "busiest_day_card": {
      "type": "Card",
      "props": {},
      "children": [
        "busiest_day_text"
      ]
    },
    "busiest_day_text": {
      "type": "Text",
      "props": {
        "text": "By observing the visitor counts and the table, the day with the highest number of visitors is easily identified. The highest visitor count is 710 on Thursday. Therefore, Thursday was the busiest day for website visitors during this week."
      },
      "children": []
    }
  }
}
